// One Slack message listing the new articles, grouped by search. No new article: no message.
const articles = $input.all().map((i) => i.json).filter((a) => a.found !== false);
if (articles.length === 0) return [];
const bySearch = {};
for (const a of articles) (bySearch[a.searchQuery] ??= []).push(a);
const blocks = Object.entries(bySearch).map(([search, list]) => {
  const lines = list.slice(0, 15).map((a) => `• <${a.url}|${(a.title ?? '').replace(/[<>|]/g, ' ')}>${a.sourceName || a.sourceDomain ? ` (${a.sourceName ?? a.sourceDomain})` : ''}`);
  if (list.length > 15) lines.push(`…and ${list.length - 15} more`);
  return `*${search}*: ${list.length} new article${list.length > 1 ? 's' : ''}\n${lines.join('\n')}`;
});
return [{ json: { text: `:newspaper: *New articles in Google News*\n\n${blocks.join('\n\n')}`, newArticles: articles.length } }];
